namespace sv_45093d1b063f4dee8c8907708d93e1c1.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

using sv_45093d1b063f4dee8c8907708d93e1c1.Models;

namespace sv_45093d1b063f4dee8c8907708d93e1c1.Services;

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_45093d1b063f4dee8c8907708d93e1c1.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClicked(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_45093d1b063f4dee8c8907708d93e1c1.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>

        <div class="form-group form-check-inline">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool?)e.Value ?? false)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task UpdateEntry(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnEntryChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

