}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.875rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #dc3545;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
