@namespace sv_45093d1b063f4dee8c8907708d93e1c1.Components.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@Entry.Name"
               @onchange="OnNameChanged" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" value="@Entry.Relationship"
               @onchange="OnRelationshipChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Entry.Email"
                   @onchange="OnEmailChanged" />
        </div>

        <div class="form-group">
            <label>Phone</label>
            <input type="tel" class="form-control" value="@Entry.Phone"
                   @onchange="OnPhoneChanged" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task OnNameChanged(ChangeEventArgs e)
    {
        Entry.Name = (string?)e.Value ?? string.Empty;
        await OnEntryChanged.InvokeAsync(Entry);
    }

    private async Task OnRelationshipChanged(ChangeEventArgs e)
    {
        Entry.Relationship = (string?)e.Value ?? string.Empty;
        await OnEntryChanged.InvokeAsync(Entry);
    }

    private async Task OnEmailChanged(ChangeEventArgs e)
    {
        Entry.Email = (string?)e.Value ?? string.Empty;
        await OnEntryChanged.InvokeAsync(Entry);
    }

    private async Task OnPhoneChanged(ChangeEventArgs e)
    {
        Entry.Phone = (string?)e.Value ?? string.Empty;
        await OnEntryChanged.InvokeAsync(Entry);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

